<script setup lang="ts">
import {computed,nextTick,onMounted,onUnmounted,ref,shallowRef,watch} from 'vue'
import {useAuthSessionStore} from '../../stores/authSession'
import {takeScanHandoff} from '../staff-scan/handoff'
import {cardApi} from './api'
import {useCardText} from './text'
import {displayName,businessDay,cardCode,dateTime} from './format'
import type {Plan,Holding,Customer,CardRequest,QrCode} from './types'
import WalletQrScanner from '../wallet/components/WalletQrScanner.vue'
import WalletQrDisplay from '../wallet/components/WalletQrDisplay.vue'
const props=defineProps<{store:string;plans:Plan[];holdings:Holding[];disabled:boolean;can:(permission:string)=>boolean}>(),emit=defineEmits<{changed:[];error:[message:string]}>(),{t,locale}=useCardText()
const origin=window.location.origin
const auth=useAuthSessionStore()
const search=ref(''),customers=ref<Customer[]>([]),customer=ref(''),card=ref(''),plan=ref(''),source=ref(''),quantity=ref(1),kind=ref('redeem'),request=ref<CardRequest|null>(null),qr=ref<QrCode|null>(null),busy=ref(false),scanMode=ref<'identity'|'authorization'|null>(null)
const customerCards=ref<Holding[]>([]),moreCustomerCards=ref(false)
const cardsLoading=ref(false),cardsError=ref('')
const chosenCustomer=ref<Customer|null>(null),searched=ref(false),searchInput=shallowRef<HTMLInputElement|null>(null)
let generation=0,lookupVersion=0,holdingsVersion=0
function resetCustomer(clearSearch=true){lookupVersion++;holdingsVersion++;chosenCustomer.value=null;customer.value='';customers.value=[];searched.value=false;customerCards.value=[];moreCustomerCards.value=false;cardsLoading.value=false;cardsError.value='';card.value='';plan.value='';source.value='';quantity.value=1;kind.value='redeem';request.value=null;qr.value=null;scanMode.value=null;if(clearSearch)search.value=''}
function selectCustomer(value:Customer){resetCustomer(false);chosenCustomer.value=value;customer.value=value.id}
function changeCustomer(){resetCustomer(false);void nextTick(()=>{searchInput.value?.focus?.();searchInput.value?.select?.()})}
onMounted(()=>{const owner=auth.user?.accountId??'',value=takeScanHandoff(props.store,owner,'cards'),g=generation;if(value)void run(async()=>{const c=await cardApi(props.store).post<Customer>('/identity',{code:value.code});if(g!==generation||auth.user?.accountId!==owner)return;selectCustomer(c)})})
const choices=computed(()=>customer.value?customerCards.value:[]),selected=computed(()=>choices.value.find(h=>h.id===card.value))
function activeCard(h:Holding){return h.status==='active'&&(!h.startsAt||Date.parse(h.startsAt)<=Date.now())&&(!h.expiresAt||Date.parse(h.expiresAt)>Date.now())}
watch(()=>props.store,()=>{generation++;resetCustomer();busy.value=false})
async function run(work:()=>Promise<void>){if(busy.value)return;const g=generation;busy.value=true;try{await work();if(g===generation)emit('changed')}catch(e){if(g===generation)emit('error',e instanceof Error?e.message:String(e))}finally{if(g===generation)busy.value=false}}
async function loadCustomer(append=false){const id=customer.value,store=props.store,g=generation,version=++holdingsVersion;if(!id){customerCards.value=[];moreCustomerCards.value=false;return}cardsLoading.value=true;cardsError.value='';try{const suffix=append?`&before=${customerCards.value.at(-1)?.id}`:'';const rows=await cardApi(store).get<Holding[]>(`/holdings?customerId=${encodeURIComponent(id)}${suffix}`);if(g===generation&&version===holdingsVersion&&id===customer.value){customerCards.value=append?[...customerCards.value,...rows]:rows;moreCustomerCards.value=rows.length===500;if(!card.value&&customerCards.value.length===1&&activeCard(customerCards.value[0]))card.value=customerCards.value[0].id;else if(card.value&&!customerCards.value.some(h=>h.id===card.value))card.value=''}}catch(e){if(g===generation&&version===holdingsVersion){cardsError.value=e instanceof Error?e.message:String(e);card.value=''}}finally{if(g===generation&&version===holdingsVersion)cardsLoading.value=false}}
watch([customer,()=>props.holdings],()=>{void loadCustomer()})
async function find(){if(props.disabled||busy.value||!search.value.trim())return;const store=props.store,g=generation,version=++lookupVersion;customers.value=[];searched.value=false;await run(async()=>{const rows=await cardApi(store).get<Customer[]>(`/customers?query=${encodeURIComponent(search.value.trim())}`);if(g!==generation||version!==lookupVersion)return;searched.value=true;if(rows.length===1)selectCustomer(rows[0]);else customers.value=rows})}
async function scan(value:string){const store=props.store,g=generation;await run(async()=>{if(scanMode.value==='identity'){const c=await cardApi(store).post<Customer>('/identity',{code:value});if(g===generation)selectCustomer(c)}else{const token=cardCode(value,window.location.origin,'CA');if(!token)throw new Error(t('noCard'));await cardApi(store).command('/authorized-redeem',{authorization:token},'request.authorized')}if(g===generation)scanMode.value=null})}
async function create(){const store=props.store,g=generation,version=lookupVersion;await run(async()=>{const chosen=selected.value,created=await cardApi(store).command<CardRequest>('/requests',{kind:kind.value,planId:chosen?.planId??plan.value,cardId:chosen?.id??null,quantity:kind.value==='stamp'?1:quantity.value},'request.create');if(g!==generation||version!==lookupVersion)return;request.value=created;const code=await cardApi(store).post<QrCode>(`/requests/${created.id}/code`);if(g===generation&&version===lookupVersion)qr.value=code})}
const timer=window.setInterval(async()=>{const r=request.value,store=props.store,g=generation;if(!r||r.status!=='pending'||busy.value)return;try{const updated=await cardApi(store).get<CardRequest>(`/requests/${r.id}`);if(g===generation&&request.value?.id===r.id){request.value=updated;if(updated.status==='completed'){qr.value=null;emit('changed')}}}catch{/* user can refresh after connection recovery */}},3000)
onUnmounted(()=>{generation++;clearInterval(timer)})
</script>
<template><section class="cards-panel cards-operations"><h2>{{t('holdings')}}</h2><div v-if="chosenCustomer" class="cards-selected-customer" role="status"><div><span>{{t('customer')}}</span><strong>{{chosenCustomer.displayName||t('customer')}}</strong><span>{{chosenCustomer.phone}}</span></div><div class="cards-actions"><button type="button" :disabled="busy" @click="changeCustomer">{{t('changeCustomer')}}</button><button type="button" :disabled="busy" @click="resetCustomer()">{{t('clearCustomer')}}</button></div></div><form v-else class="cards-actions cards-customer-search" @submit.prevent="find"><input ref="searchInput" v-model="search" :disabled="busy||disabled" :placeholder="t('search')" :aria-label="t('search')"><button class="primary" :disabled="busy||disabled||!search.trim()">{{t('searchAction')}}</button><button type="button" :disabled="busy||disabled" @click="scanMode='identity'">{{t('scan')}} · {{t('customer')}}</button></form><WalletQrScanner v-if="scanMode" :purpose="scanMode==='identity'?'identity':'cardAuthorization'" auto-start :disabled="busy||disabled" @code="scan"/><div v-if="!chosenCustomer&&customers.length" class="cards-customer-results" :aria-label="t('customer')"><p>{{t('chooseCustomer')}}</p><button v-for="c in customers" :key="c.id" class="cards-customer-result" type="button" :disabled="busy||disabled" @click="selectCustomer(c)"><strong>{{c.displayName||t('customer')}}</strong><span>{{c.phone}}</span></button></div><p v-else-if="!chosenCustomer&&searched" class="cards-empty" role="status">{{t('noCustomers')}}</p><div class="cards-grid cards-customer-fields"><label>{{t('holdings')}}<select v-model="card" :disabled="!customer||cardsLoading||!!cardsError||!choices.length||busy||disabled"><option value="">{{t(!customer?'selectCustomer':cardsLoading?'loading':cardsError?'cardsLoadFailed':!choices.length?'noCustomerCards':'select')}}</option><option v-for="h in choices" :key="h.id" :value="h.id" :disabled="!activeCard(h)">{{displayName(h.snapshot,locale)}} · {{t(h.kind)}} · {{t('today')}} {{h.available}}</option></select></label><label>{{t('plans')}}<select v-model="plan" :disabled="busy||disabled"><option value="">{{t('select')}}</option><option v-for="p in plans.filter(p=>p.status==='active')" :key="p.id" :value="p.id">{{displayName(p,locale)}}</option></select></label></div><p v-if="customer&&!cardsLoading&&!cardsError&&!choices.length" class="cards-notice" role="status">{{t('noCustomerCardsHint')}}</p><div v-if="cardsError" class="cards-error" role="alert">{{t('cardsLoadFailed')}} · {{cardsError}} <button type="button" :disabled="busy||disabled||cardsLoading" @click="loadCustomer()">{{t('refresh')}}</button></div><div class="cards-actions"><button v-if="can('wallet.cards.stamp')" :disabled="!customer||!plans.some(p=>p.id===plan&&p.status==='active'&&p.kind==='stamp')||busy||disabled" @click="run(async()=>{await cardApi(store).command('/enroll',{customerId:customer,planId:plan},'enroll.staff')})">{{t('claim')}}</button></div><button v-if="customer&&moreCustomerCards" :disabled="busy||disabled" @click="loadCustomer(true)">{{t('loadMore')}}</button><div v-if="selected" class="cards-notice"><strong>{{displayName(selected.snapshot.product,locale)}}</strong><p>{{t('remaining')}}: {{selected.remaining??t('unlimited')}} · {{t('today')}}: {{selected.available}}</p><p>{{t('progress')}}: {{selected.progress}} / {{selected.snapshot.stampTarget}} · {{t('expires')}}: {{dateTime(selected.expiresAt,selected.timezone)}}</p></div>
<div v-if="selected?.kind==='stamp'&&can('wallet.cards.stamp')" class="cards-actions"><input v-model="source" :placeholder="t('source')" maxlength="200" style="max-width:300px"><button :disabled="!source||busy||disabled" @click="run(async()=>{await cardApi(store).command('/stamps',{cardId:card,source},'stamp');source=''})">{{t('grant')}}</button></div><div class="cards-grid cards-redemption-fields"><label>{{t('kind')}}<select v-model="kind"><option value="redeem">{{t('redeem')}}</option><option value="stamp">{{t('stamp')}}</option></select></label><label>{{t('quantity')}}<input v-model.number="quantity" type="number" min="1" max="1000000" :disabled="kind==='stamp'"></label></div><div class="cards-actions"><button class="primary" :disabled="busy||disabled||cardsLoading||!!cardsError||(customer?(!selected||!activeCard(selected)):!plan)||!can(kind==='stamp'?'wallet.cards.stamp':'wallet.cards.redeem')" @click="create">{{t('merchantCode')}}</button><button v-if="can('wallet.cards.redeem')||can('wallet.cards.stamp')" :disabled="busy||disabled" @click="scanMode='authorization'">{{t('scanCard')}}</button><button v-if="request?.status==='pending'" :disabled="busy" @click="run(async()=>{if(request){request=await cardApi(store).command(`/requests/${request.id}/cancel`,{},'request.cancel');qr=null}})">{{t('cancel')}}</button></div><p class="cards-notice">{{t('dailyHint')}}</p><div v-if="qr&&request" class="cards-qr"><WalletQrDisplay :value="`${origin}/wallet/${store}/cards#card=${qr.code}`" :expires-at="qr.expiresAt"/><a :href="`/wallet/${store}/cards#card=${qr.code}`" target="_blank" rel="noreferrer">{{t('customer')}} · {{t('details')}}</a></div><p v-if="request">{{t('request')}} {{request.id.slice(0,8)}} · {{t(request.status)}}</p></section></template>
